    public static final String MODID = "occultism";
    public static final String NAME = "Occultism";
    public static final Logger LOGGER = LogUtils.getLogger();
    public static final OccultismServerConfig SERVER_CONFIG = OccultismServerConfig.get();
    public static final OccultismCommonConfig COMMON_CONFIG = OccultismCommonConfig.get();
    public static final OccultismClientConfig CLIENT_CONFIG = OccultismClientConfig.get();
    public static final OccultismStartupConfig STARTUP_CONFIG = OccultismStartupConfig.get();
    public static final SelectedBlockRenderer SELECTED_BLOCK_RENDERER = new SelectedBlockRenderer();
    public static final ThirdEyeEffectRenderer THIRD_EYE_EFFECT_RENDERER = new ThirdEyeEffectRenderer();
    public static final DebugHelper DEBUG = new DebugHelper();
    public static Occultism INSTANCE;

    public Occultism(IEventBus modEventBus, ModContainer modContainer) {
        INSTANCE = this;
        modContainer.registerConfig(Type.SERVER, SERVER_CONFIG.spec);
        modContainer.registerConfig(Type.CLIENT, CLIENT_CONFIG.spec);
        modContainer.registerConfig(Type.STARTUP, STARTUP_CONFIG.spec);

        OccultismEffects.EFFECTS.register(modEventBus);
        OccultismPotions.POTIONS.register(modEventBus);
        OccultismRecipes.RECIPE_TYPES.register(modEventBus);
        OccultismRecipes.RECIPES.register(modEventBus);
        OccultismBlocks.BLOCKS.register(modEventBus);
        OccultismItems.ITEMS.register(modEventBus);
        OccultismCreativeModeTabs.CREATIVE_MODE_TABS.register(modEventBus);
        OccultismBlockEntities.BLOCK_ENTITIES.register(modEventBus);
        OccultismContainers.CONTAINERS.register(modEventBus);
        OccultismEntities.ENTITIES.register(modEventBus);
        OccultismSounds.SOUNDS.register(modEventBus);
        OccultismParticles.PARTICLES.register(modEventBus);
        OccultismFeatures.FEATURES.register(modEventBus);
        OccultismLootModifiers.LOOT_MODIFIERS.register(modEventBus);
        OccultismSensors.SENSORS.register(modEventBus);
        OccultismMemoryTypes.MEMORY_MODULE_TYPES.register(modEventBus);
        OccultismDataStorage.ATTACHMENT_TYPES.register(modEventBus);
        OccultismAdvancements.TRIGGER_TYPES.register(modEventBus);
        OccultismDataComponents.DATA_COMPONENTS.register(modEventBus);
        OccultismRecipeResults.RECIPE_RESULT_TYPES.register(modEventBus);
        OccultismConditionCodecs.CONDITION_CODECS.register(modEventBus);
        OccultismRecipeDisplays.RECIPE_DISPLAYS.register(modEventBus);
        OccultismFoods.CONSUME_EFFECT_TYPES.register(modEventBus);
        GameTestRegistry.TEST_FUNCTIONS.register(modEventBus);

        //now register the custom registries
        OccultismSpiritJobs.JOBS.register(modEventBus);
        OccultismRituals.RITUAL_FACTORIES.register(modEventBus);

        //register event buses
        modEventBus.addListener(OccultismRegistries::onRegisterRegistries);
        modEventBus.addListener(EventPriority.HIGHEST, OccultismCapabilities::onRegisterCapabilities);
        modEventBus.addListener(GameTestRegistry::onRegisterGameTests);
        modEventBus.addListener(this::commonSetup);
        modEventBus.addListener(this::onEntityAttributeCreation);
        modEventBus.addListener(this::serverSetup);
        modEventBus.addListener(Networking::register);

        NeoForge.EVENT_BUS.addListener(OccultismDataStorage::onPlayerClone);
        NeoForge.EVENT_BUS.addListener(OccultismDataStorage::onJoinWorld);
        NeoForge.EVENT_BUS.addListener(OccultismRecipeManager.get()::onDatapackSync);

        if (FMLEnvironment.getDist() == Dist.CLIENT) {
            NeoForge.EVENT_BUS.addListener(OccultismRecipeManagerClient::onRecipesReceived);
            NeoForge.EVENT_BUS.addListener(OccultismRecipeManagerClient::onClientLogout);
            modEventBus.addListener(ClientSetupEventHandler::onRegisterMenuScreens);
            modEventBus.addListener(ClientSetupEventHandler::onRegisterRenderPipelines);
            modEventBus.addListener(ClientSetupEventHandler::onRegisterConditionalItemModelProperties);
            modEventBus.addListener(ClientSetupEventHandler::onRegisterRangeSelectItemModelProperties);
            modEventBus.addListener(ColorEventHandler::onRegisterBlockColorHandlers);
            ClientSetupEventHandler.registerConfigScreen(modContainer);
        }

    }

    private void commonSetup(final FMLCommonSetupEvent event) {
        OccultismModonomiconPageTypeRegistry.bootstrap();

        event.enqueueWork(() -> {
            BlockEntityType.CAMPFIRE.validBlocks = Stream.concat(
                    BlockEntityType.CAMPFIRE.validBlocks.stream(),
                    Stream.of(OccultismBlocks.SPIRIT_CAMPFIRE.get())
            ).collect(ImmutableSet.toImmutableSet());
            BlockEntityType.SHELF.validBlocks = Stream.concat(
                    BlockEntityType.SHELF.validBlocks.stream(),
                    Stream.of(OccultismBlocks.OTHERPLANKS_SHELF.get())
            ).collect(ImmutableSet.toImmutableSet());
            DispenserBlock.registerBehavior(
                    OccultismItems.OTHERPLANKS_BOAT.get(),
                    new BoatDispenseItemBehavior(OccultismEntities.OTHERPLANKS_BOAT.get())
            );
            DispenserBlock.registerBehavior(
                    OccultismItems.OTHERPLANKS_BOAT_CHEST.get(),
                    new BoatDispenseItemBehavior(OccultismEntities.OTHERPLANKS_BOAT_CHEST.get())
            );
            DispenserBlock.registerBehavior(OccultismItems.NATURE_PASTE, new OptionalDispenseItemBehavior() {
                @Override
                protected @NonNull ItemStack execute(@NonNull BlockSource source, @NonNull ItemStack dispensed) {
                    this.setSuccess(true);
                    ServerLevel level = source.level();
                    BlockPos target = source.pos().relative(source.state().getValue(DispenserBlock.FACING));
                    if (!NaturePasteItem.growCustom(dispensed, level, target)
                            && !NaturePasteItem.applyBonemeal(dispensed, level, target, null)
                            && !NaturePasteItem.growWaterPlant(dispensed, level, target, null)) {
                        this.setSuccess(false);
                    } else if (!level.isClientSide()) {
                        dispensed.hurtAndBreak(1, level, (LivingEntity) null, (item) -> {});
                        level.levelEvent(1505, target, 15);
                    }

                    return dispensed;
                }
            });
            DispenserBlock.registerBehavior(
                    OccultismItems.FLAMING_PASTE.get(),
                    new FireballDispenseBehavior(OccultismItems.FLAMING_PASTE.get())
            );
        });

        //Register entity attributes on single thread

        LOGGER.info("Common setup complete.");
    }

