import net.minecraft.world.phys.Vec3;

import java.util.function.Supplier;

public abstract class ChangeWeatherJob extends SpiritJob {

    protected int currentChangeTicks;
    protected Supplier<Integer> requiredChangeTicks;

    public ChangeWeatherJob(SpiritEntity entity, Supplier<Integer> requiredChangeTicks) {
        super(entity);
        this.requiredChangeTicks = requiredChangeTicks;
    }

    @Deprecated
    protected static int getDuration(RandomSource randomSource, int time, IntProvider timeProvider) {
        return time == -1 ? timeProvider.sample(randomSource) : time;
    }

    @Override
    public void onInit() {

    }

    @Override
    public void cleanup() {
        //in this case called on spirit death
        for (int i = 0; i < 5; i++) {
            ((ServerLevel) this.entity.level())
                    .sendParticles(ParticleTypes.LARGE_SMOKE, this.entity.getX() + this.entity.level().getRandom().nextGaussian(),
                            this.entity.getY() + 0.5 + this.entity.level().getRandom().nextGaussian(), this.entity.getZ() + this.entity.level().getRandom().nextGaussian(), 5,
                            0.0, 0.0, 0.0,
                            0.0);
        }

    }

    @Override
    public void update() {
        super.update();

        this.currentChangeTicks++;
        if (!this.entity.swinging) {
            this.entity.swing(InteractionHand.MAIN_HAND);
        }
        if (this.entity.level().getGameTime() % 2 == 0) {
            ((ServerLevel) this.entity.level())
                    .sendParticles(ParticleTypes.SMOKE, this.entity.getX(),
                            this.entity.getY() + 0.5, this.entity.getZ(), 3,
                            0.5, 0.0, 0.0,
                            0.0);
        }

        if (this.currentChangeTicks == this.requiredChangeTicks.get()) {
            this.changeWeather();

            LightningBolt lightningboltentity = EntityType.LIGHTNING_BOLT.create(this.entity.level(), EntitySpawnReason.COMMAND);
            lightningboltentity.snapTo(Vec3.atBottomCenterOf(this.entity.blockPosition()));
            lightningboltentity.setVisualOnly(true);

            this.entity.die(this.entity.damageSources().lightningBolt());
            this.entity.remove(RemovalReason.DISCARDED);
        }
    }

    @Override
    public CompoundTag writeJobToNBT(CompoundTag compound, Provider provider) {
        compound.putInt("currentChangeTicks", this.currentChangeTicks);
        compound.putInt("requiredChangeTicks", this.requiredChangeTicks.get());
        return super.writeJobToNBT(compound, provider);
    }

    @Override
    public void readJobFromNBT(CompoundTag compound, Provider provider) {
        super.readJobFromNBT(compound, provider);
        this.currentChangeTicks = compound.getIntOr("currentChangeTicks", 0);
        var requiredChangeTicks = compound.getIntOr("requiredChangeTicks", 0);
        this.requiredChangeTicks = () -> requiredChangeTicks;
    }

    public abstract void changeWeather();

}

